-- The two checklists published on 2026-11-23: When Your Child Is Sick at Home
-- (Sick Child) and Your First Weeks Managing a Team (Managing People).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-23`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-your-child-is-sick-at-home', 'When Your Child Is Sick at Home', 'Open this on a day you are suddenly home with a sick child, with work to cancel and a long afternoon ahead. It helps you handle the practical part quickly and get through the day without running yourself into the ground.', 'Sick Child', '["Send the work message first, without detail — One short line now saves you apologizing all morning.", "Write down the temperature and the time — A simple log answers the first question a nurse will ask.", "Set up one nest and stay in it — Moving a sick child from room to room tires you both out.", "Put drinks within their reach — Small sips beat a glass they have to ask for.", "Decide now what today is not about — The laundry and the inbox are tomorrow''s problem.", "Let the screen rules go for the day — A settled child is worth more than a rule today.", "Eat something yourself at a set time — The person doing the caring skips meals first and feels it by evening.", "Ask someone to take an hour this evening — A short handoff is what keeps you going tomorrow."]'::jsonb, 'as needed', array['Parenting', 'Caregiving', 'Self-Care']::text[], 1, '2026-11-23T16:00:00+00:00'::timestamptz),
  ('your-first-weeks-managing-a-team', 'Your First Weeks Managing a Team', 'Open this when you have just started leading people, perhaps the ones who were your peers last month, and you are unsure what the job actually is. It gives you a few first moves that build trust before you change anything.', 'Managing People', '["Ask each person what they need from you — The answers are more useful than any plan you arrive with.", "Change nothing in the first two weeks — Listening first buys you the credit to change things later.", "Book a short regular time with each one — A standing slot beats an open door nobody walks through.", "Say out loud what you will decide alone — Clear lines stop people guessing where their say ends.", "Pass on the credit by name — Naming who did what costs you nothing and buys a great deal.", "Give awkward feedback early and small — A quiet word in week one saves a hard talk in month three.", "Find your own place to complain — Your team is not where your frustration goes.", "Protect one block for your own work — A calendar of nothing but meetings is how new managers drown."]'::jsonb, 'weekly', array['Work', 'Communication', 'Assertiveness']::text[], 1, '2026-11-23T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
